package zip.hedlund.pureedgesim.edgesdk.model;

import java.util.Objects;

/**
 * A stream of offloadable tasks generated by each end device it applies to.
 * Arrivals are Poisson with the given rate; every task has the same size.
 *
 * @param name          workload name, reported per task
 * @param ratePerMinute mean tasks per minute and device
 * @param lengthMi      computation, million instructions
 * @param inputBytes    bytes sent to the executing node
 * @param outputBytes   bytes of the result sent back to the device
 * @param deadlineS     the task fails when its result is not back within this time
 * @param containerMb   RAM held on the executing node while running
 */
public record WorkloadSpec(String name, double ratePerMinute, double lengthMi, long inputBytes, long outputBytes,
		double deadlineS, double containerMb) {

	public WorkloadSpec {
		Objects.requireNonNull(name, "name");
		if (!(ratePerMinute > 0) || !(lengthMi > 0) || inputBytes < 0 || outputBytes < 0 || !(deadlineS > 0)
				|| containerMb < 0)
			throw new IllegalArgumentException(name + ": invalid workload parameters");
	}

	public WorkloadSpec withRatePerMinute(double rate) {
		return new WorkloadSpec(name, rate, lengthMi, inputBytes, outputBytes, deadlineS, containerMb);
	}

	public WorkloadSpec withLengthMi(double mi) {
		return new WorkloadSpec(name, ratePerMinute, mi, inputBytes, outputBytes, deadlineS, containerMb);
	}

	public WorkloadSpec withSizes(long in, long out) {
		return new WorkloadSpec(name, ratePerMinute, lengthMi, in, out, deadlineS, containerMb);
	}

	public WorkloadSpec withDeadlineS(double deadline) {
		return new WorkloadSpec(name, ratePerMinute, lengthMi, inputBytes, outputBytes, deadline, containerMb);
	}

	public WorkloadSpec named(String newName) {
		return new WorkloadSpec(newName, ratePerMinute, lengthMi, inputBytes, outputBytes, deadlineS, containerMb);
	}
}
